            { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filter", details: "Replace the panel filter. Do NOT oil the filter, as oil will instantly destroy the highly sensitive integrated MAF sensor.", parts: ["Mann Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" },
            { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter to prevent HVAC odors.", parts: ["Mahle Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "25 EUR" },
            { interval: "60,000 km", timeLimit: "6 years", task: "Fuel Filter Replacement", details: "The fuel filter contains the integrated pressure regulator. Replace to ensure smooth idling and correct fuel pressure.", parts: ["Mahle Fuel Filter"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }
