          engineMechanical: [ { interval: "5 Years", timeLimit: "5 years", task: "Battery Service", details: "Replace lead-acid battery under the floorboard.", parts: ["60Ah Battery"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "100 EUR" }, { interval: "As Needed", timeLimit: "Unlimited", task: "Alternator Replacement", details: "Water-cooled alternators are a nightmare to replace.", parts: ["Bosch Alternator"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "250 EUR" } ]
