        engineeringData: { blockDesign: "Inline-4, Heavy cast-iron block with an aluminum cylinder head. Transverse MFA layout. This engine is a joint venture with Renault (K9K). It provides phenomenal fuel efficiency.", crankshaft: "Forged Steel, supported by 5 main bearings.", pistonSpeed: "10.6 m/s @ 4000 RPM.", alternator: "150A Valeo/Bosch.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy featuring internal oil cooling galleries.", wristPinDiameter: "26 mm.", connectingRodLength: "133.6 mm. (Rod bearings are a known weak point).", rodBoltSize: "M8.", crankMainJournal: "48.0 mm.", crankRodJournal: "44.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "8-valve SOHC design. Highly restrictive at upper RPMs, engineered purely for low-end torque.", valveSizes: "Intake: 33.5 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Very mild profile.", lifterType: "Solid lifters.", specialFeature: "Utilizes a single overhead camshaft." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement pump.", thermostatOpening: "83°C Mechanical." }, fuelSystem: { systemType: "Continental Common Rail.", maxPressure: "1600 Bar.", injectors: "Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "280 Nm", maxSafePowerStock: "130 hp", maxSafeRPM: "4500 RPM", weakestLink: "Connecting Rod Bearings, 7G-DCT Clutches." }, electrical: { coils: "N/A", ecu: "Continental SID310" } },
