        engineeringData: { blockDesign: "Inline-4, Heavy cast-iron block with an aluminum cylinder head. Transverse MFA layout. This engine is a legendary joint venture with Renault (K9K). It abandons the timing chains of genuine Mercedes engines for a traditional, quiet timing belt. BE models feature aerodynamic underbody panels, lowered suspension, and a closed upper grille to reduce drag.", crankshaft: "Forged Steel, supported by 5 main bearings, highly balanced.", pistonSpeed: "10.6 m/s @ 4000 RPM.", alternator: "150A Valeo/Bosch 'Intelligent' Alternator (BE specific, recoups energy during braking and limits load during acceleration).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy featuring internal oil cooling galleries.", wristPinDiameter: "26 mm.", connectingRodLength: "133.6 mm. (Rod bearings are a known weak point, especially stressed by Start/Stop).", rodBoltSize: "M8.", crankMainJournal: "48.0 mm.", crankRodJournal: "44.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "8-valve SOHC design. Highly restrictive at upper RPMs, engineered purely for massive low-end torque and extreme fuel economy.", valveSizes: "Intake: 33.5 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Very mild profile.", lifterType: "Solid lifters (requires manual valve clearance checks at extreme mileages).", specialFeature: "Utilizes a single overhead camshaft to operate 8 valves, vastly reducing internal friction." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement pump.", thermostatOpening: "83°C Mechanical thermostat." }, fuelSystem: { systemType: "Continental Common Rail Direct Injection with AdBlue SCR exhaust aftertreatment (Euro 6).", maxPressure: "1600 Bar.", injectors: "Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "320 Nm", maxSafePowerStock: "145 hp", maxSafeRPM: "4500 RPM", weakestLink: "Connecting Rod Bearings, Euro 6 AdBlue/DPF System, 7G-DCT Transmission Clutches." }, electrical: { coils: "N/A", ecu: "Continental SID310 (Highly optimized software map for 109hp and maximum MPG; heavily utilizes ECO Start/Stop)." } },
