      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 yr", task: "Engine Oil & Filter", details: "Prevents tensioner failure. MUST use MB 229.71.", parts: ["5.1L 0W-20"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "3 yrs", task: "Engine Air Filter", details: "Replace panel filter.", parts: ["Mann Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "2 yrs", task: "Cabin Microfilter", details: "Replace interior filter.", parts: ["Mahle"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "30,000 km", timeLimit: "3 yrs", task: "Fuel Filter", details: "Replace inline filter.", parts: ["Mahle"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
      ignitionAndEngine: [ { interval: "60,000 km", timeLimit: "5 yrs", task: "Spark Plugs", details: "Requires 14mm thin-wall.", parts: ["NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "100,000 km", timeLimit: "8 yrs", task: "Ignition Coils", details: "Cure misfires.", parts: ["Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "160 EUR" }, { interval: "80,000 km", timeLimit: "N/A", task: "Walnut Blasting", details: "Blast carbon sludge off valves.", parts: ["Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "As Needed", timeLimit: "N/A", task: "Thermostat Replacement", details: "If P0128 appears.", parts: ["BorgWarner"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }, { interval: "100,000 km", timeLimit: "N/A", task: "GPF Regeneration", details: "Force burn via OBD2.", parts: ["OBD2 Service"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
