    sisterModels: [ { name: "Mercedes-Benz A 250 (W177)", note: "The USA A 220 is mechanically identical to the European A 250, just artificially restricted in software." } ],
    tuningPotential: [ { stage: "Stage 1 (Software Flash)", power: "240 - 250 hp", notes: "Instantly unlocks 50+ horsepower safely. The stock internals handle this effortlessly.", zeroToHundred: "6.2s", hundredToTwoHundred: "16.5s" }, { stage: "Stage 2 (Downpipe & Tune)", power: "260 - 270 hp", notes: "Requires high-flow downpipe. The 7G-DCT transmission clutches will begin to slip if abused.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 3 (Hybrid Turbo)", power: "300 - 320 hp", notes: "Requires larger hybrid turbo. The transmission will fail catastrophically under the load.", zeroToHundred: "5.1s", hundredToTwoHundred: "12.5s" } ],
