    engineeringData: { blockDesign: "Inline-4, Heavy cast-iron block with aluminum cylinder head. Transverse MFA2 layout. Renault K9K evolution utilizing a front timing belt.", crankshaft: "Forged Steel, 5 mains.", pistonSpeed: "10.6 m/s @ 4000 RPM.", alternator: "150A Valeo/Bosch.", rotatingAssembly: { pistonConstruction: "Cast aluminum.", wristPinDiameter: "26 mm.", connectingRodLength: "133.6 mm.", rodBoltSize: "M8.", crankMainJournal: "48.0 mm.", crankRodJournal: "44.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston.", intakePortFlow: "8-valve SOHC design.", valveSizes: "In: 33.5 mm / Ex: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel profile.", lifterType: "Solid lifters.", specialFeature: "Single overhead camshaft." }, oilAndCooling: { oilSquirters: "Yes.", oilPumpType: "Chain-driven variable vane.", thermostatOpening: "83°C Mechanical." }, fuelSystem: { systemType: "Continental Common Rail.", maxPressure: "2000 Bar.", injectors: "Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "320 Nm", maxSafePowerStock: "145 hp", maxSafeRPM: "4500 RPM", weakestLink: "Rod Bearings, Euro 6 AdBlue/DPF System, 7DCT300 Clutches." }, electrical: { coils: "N/A", ecu: "Bosch MD1 (Software limited to exactly 109hp for tax reasons)." } },
