    sisterModels: [ { name: "Mercedes-Benz B 200 d (W246)", note: "Shares the identical OM654 2.0L engine." }, { name: "Mercedes-Benz CLA 200 d (C118)", note: "Shares the exact same chassis, interior, and 2.0L powertrain." } ],
    tuningPotential: [ { stage: "Stage 1 (Software Flash)", power: "190 - 200 hp", notes: "THE ULTIMATE UPGRADE. Instantly unlocks 40+ horsepower safely, restoring it to A 220 d specifications. The 8G-DCT clutches are the limiting factor.", zeroToHundred: "7.6s", hundredToTwoHundred: "24.5s" }, { stage: "Stage 2 (EGR & AdBlue Delete + Tune)", power: "205 - 215 hp", notes: "Electronically disabling the EGR and AdBlue systems prevents carbon sludge buildup and eliminates NOx sensor failures.", zeroToHundred: "7.2s", hundredToTwoHundred: "23.0s" }, { stage: "Stage 3 (Hybrid Turbo)", power: "230 - 240 hp", notes: "Requires rebuilding the turbocharger. The 8G-DCT transmission clutch packs will slip severely.", zeroToHundred: "6.6s", hundredToTwoHundred: "19.0s" } ],
