    torqueSpecs: [ { part: "Engine Oil Drain Plug", value: "30 Nm", note: "Always use a new copper crush washer." }, { part: "Glow Plugs", value: "11 Nm", note: "CRITICAL: Soak heavily in penetrant; remove strictly on a fully hot engine to avoid snapping in the aluminum head." }, { part: "Wheel Bolts", value: "130 Nm", note: "Apply sequentially in a crisscross pattern." }, { part: "DCT Transmission Pan", value: "8 Nm", note: "Use new aluminum bolts; they are single-use stretch bolts." }, { part: "Water Pump Bolts", value: "12 Nm", note: "Tighten carefully to avoid cracking the housing." } ],
    engineeringData: { blockDesign: "Inline-4, Ultra-lightweight all-aluminum block with Nanoslide cylinder wall coating. Features forged steel pistons running inside aluminum cylinders. The timing chain drive is located at the absolute rear of the engine block.", crankshaft: "Forged Steel, 5 mains, Lanchester balance shafts.", pistonSpeed: "11.2 m/s @ 4000 RPM.", alternator: "150A Valeo/Bosch.", rotatingAssembly: { pistonConstruction: "Forged Steel pistons with stepped bowls.", wristPinDiameter: "30 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9.", crankMainJournal: "60.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Direct injection stepped-bowl.", intakePortFlow: "16-valve DOHC.", valveSizes: "In: 29.5 mm / Ex: 27.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel profile.", lifterType: "Hydraulic roller.", specialFeature: "Rear-mounted camshaft gears." }, oilAndCooling: { oilSquirters: "Yes.", oilPumpType: "Chain-driven variable vane.", thermostatOpening: "90°C Mechanical." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection with AdBlue SCR.", maxPressure: "2050 Bar.", injectors: "Bosch Solenoid." }, tuningLimits: { maxSafeTorqueStock: "450 Nm", maxSafePowerStock: "210 hp", maxSafeRPM: "4500 RPM", weakestLink: "Rear Timing Chain, Euro 6 AdBlue/DPF System, Vacuum Water Pump, 8G-DCT Clutches." }, electrical: { coils: "N/A", ecu: "Bosch MD1 (Software artificially limits the engine to exactly 136hp for tax purposes)." } },
