      oilAndFilters: [ { interval: "10k km", timeLimit: "1 yr", task: "Engine Oil & Filter", details: "Prevents timing chain tensioner failure. MUST use MB 229.52.", parts: ["6.0L 0W-20/5W-30"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "95 EUR" }, { interval: "30k km", timeLimit: "3 yrs", task: "Air Filter", details: "Replace panel filter.", parts: ["Mann Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30k km", timeLimit: "3 yrs", task: "Fuel Filter", details: "Protects high-pressure pump.", parts: ["Mahle Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
      ignitionAndEngine: [ { interval: "Immediately", timeLimit: "N/A", task: "Listen for Timing Chain Rattle", details: "If heard, replace tensioner immediately.", parts: ["Tensioner"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "2,500+ EUR" }, { interval: "100k km", timeLimit: "8 yrs", task: "Glow Plugs", details: "Do on hot engine.", parts: ["Beru Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "80k km", timeLimit: "N/A", task: "EGR Cleaning", details: "Scrape carbon soot.", parts: ["Carb Cleaner"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "100k km", timeLimit: "N/A", task: "DPF Chemical Cleaning", details: "Clear ash blockages.", parts: ["Additive"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "As Needed", timeLimit: "N/A", task: "Vacuum Line Inspection", details: "Check for coolant migration.", parts: ["Lines"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" } ],
