    sisterModels: [ { name: "Mercedes-Benz A 160 BlueEfficiency (W169)", note: "Shares the exact same M266.920 engine, Autotronic transmission, and ECO Start/Stop system." } ],
    tuningPotential: [ { stage: "Stage 1 (Software Flash)", power: "105 - 110 hp", notes: "Because it is a naturally aspirated 1.5L 8-valve engine, tuning gains are virtually nonexistent. A Stage 1 flash will slightly sharpen the electronic throttle response.", zeroToHundred: "12.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2 (Exhaust & Intake)", power: "110 - 115 hp", notes: "The volumetric efficiency of the 8-valve SOHC head is too poor to see meaningful gains. Absolutely not recommended.", zeroToHundred: "12.3s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Forced Induction)", power: "N/A", notes: "Physically impossible to fit a turbocharger due to the extreme 59-degree tilt and sandwich floor packaging.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" } ],
