    engineeringData: { blockDesign: "Inline-4, Heavy cast-iron block with aluminum cylinder head. Mounted transversely in the unique W245 'Sandwich Floor' platform. The engine is tilted forward at an extreme 59-degree angle for crash safety, burying auxiliary components under the firewall.", crankshaft: "Cast Iron, 5 mains.", pistonSpeed: "13.8 m/s @ 5500 RPM.", alternator: "120A Valeo/Bosch.", rotatingAssembly: { pistonConstruction: "Cast aluminum.", wristPinDiameter: "20 mm.", connectingRodLength: "138 mm.", rodBoltSize: "M8.", crankMainJournal: "48.0 mm.", crankRodJournal: "44.0 mm.", rodRatio: "1.65." }, cylinderHead: { combustionChamberVol: "Hemispherical chamber.", intakePortFlow: "8-valve SOHC design. Highly restrictive.", valveSizes: "In: 35.0 mm / Ex: 31.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Very mild profile.", lifterType: "Hydraulic bucket.", specialFeature: "Standard single spark architecture." }, oilAndCooling: { oilSquirters: "No.", oilPumpType: "Chain-driven gear pump.", thermostatOpening: "87°C Mechanical." }, fuelSystem: { systemType: "Bosch Multi-Point Port Fuel Injection.", maxPressure: "3.8 Bar.", injectors: "Bosch Solenoid." }, tuningLimits: { maxSafeTorqueStock: "180 Nm", maxSafePowerStock: "130 hp", maxSafeRPM: "6000 RPM", weakestLink: "Autotronic CVT Push-Belt, Extremely Low Volumetric Efficiency." }, electrical: { coils: "Twin-pack wasted spark coil.", ecu: "Siemens SIM266 (Prone to heat failure)." } },
