    riskRating: 8, model3DPath: "/images/brands/mercedes/B-Class/W245/w2452.glb", model3DScale: 0.1, model3DRotation: [0, 0, 0], manualLightPositions: { headlights: { x: 0.16, y: -0.02, z: 0.4 } }, lightSettings: { headlightAngle: 0.25, headlightIntensity: 100, headlightOpacity: 0.5, headlightRadiusTop: 0.02, headlightTargetDistance: 4.5, headlightPenumbra: 0.1, meshGlowHeadlight: 18, meshGlowTaillight: 6, meshGlowDrl: 15, useBloom: true }, hotspotSettings: { distanceFactor: 1 },
