      { stage: "Stage 2 (EGR Delete & Tune)", power: "145 - 150 hp", notes: "Electronically disabling the EGR system (where legal) prevents carbon sludge buildup and allows for slightly more aggressive tuning.", zeroToHundred: "9.5s", hundredToTwoHundred: "N/A" },
      { stage: "Stage 3 (Hybrid Turbo)", power: "N/A", notes: "Not financially viable. Upgrading the turbo requires dropping the engine, and the CVT cannot handle the power.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" }
