      fluidsAndDrivetrain: [ { interval: "60,000 km", timeLimit: "5 years", task: "Autotronic CVT Transmission Fluid & Filter", details: "CRITICAL: Drain fluid and replace filter in the pan. Neglect leads directly to push-belt failure under the 300Nm diesel torque.", parts: ["6.0L MB 236.20", "CVT Filter", "Pan Gasket"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Manual Transmission Fluid", details: "Drain and refill the 6-speed manual gearbox.", parts: ["1.8L 75W-80 API GL-4"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "60 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 fluid.", parts: ["1.0L DOT 4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Engine Coolant Flush", details: "Flush the cooling system to protect the water pump and heater core.", parts: ["7.5L MB 325.0 Blue"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ],
      oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Engine Oil & Filter Change", details: "CRITICAL: Regular oil changes prevent timing chain tensioner failure. Use high-quality MB 229.51 if DPF equipped.", parts: ["5.8L 5W-30 (MB 229.51)", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel filter to allow the turbo to breathe.", parts: ["Mann Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace interior HVAC filter.", parts: ["Mahle Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Fuel Filter Replacement", details: "CRITICAL: Protects the high-pressure common rail pump from contamination.", parts: ["Mahle Fuel Filter"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" } ],
      ignitionAndEngine: [ { interval: "100,000 km", timeLimit: "N/A", task: "Injector Seal Inspection/Replacement", details: "CRITICAL: Remove engine cover and inspect injectors for black, tar-like substance. Replace copper seals proactively to prevent 'Black Death'.", parts: ["Injector Seals", "Stretch Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plug Replacement", details: "MUST be done on a fully hot engine. Crucial for cold starts.", parts: ["4x Beru Glow Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "80,000 km", timeLimit: "Unlimited", task: "EGR Valve & Intake Cleaning", details: "Remove and scrape thick carbon soot out of the EGR valve.", parts: ["Carb Cleaner"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "As Needed", timeLimit: "Unlimited", task: "Thermostat Replacement", details: "If engine temperature drops on highway, replace thermostat to restore DPF regeneration.", parts: ["Mahle Thermostat"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "Immediately", timeLimit: "N/A", task: "Listen for Timing Chain Rattle", details: "CRITICAL: Every cold start, listen for a rattle. If heard, replace tensioner immediately.", parts: ["Tensioner"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1,800+ EUR" } ],
      preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace drive system proactively. Access is terrible if it snaps.", parts: ["INA Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "200 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Front Coil Springs", details: "Inspect and replace front springs; they are highly prone to snapping under the heavy diesel engine.", parts: ["Sachs Springs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "As Needed", timeLimit: "N/A", task: "Starter Motor Replacement", details: "WARNING: Requires dropping the entire front subframe and engine.", parts: ["Bosch Starter"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1,000+ EUR" } ],
