    tuningPotential: [ { stage: "Stage 1 (Software Flash)", power: "165 - 170 hp", notes: "An aftermarket ECU flash safely unlocks massive torque and over 25 horsepower. WARNING: The Autotronic CVT will likely slip and fail if the torque is pushed over 320 Nm. Tuning is only recommended for manual models.", zeroToHundred: "8.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2 (EGR Delete & Tune)", power: "170 - 175 hp", notes: "Electronically disabling the EGR system (where legal) prevents carbon sludge buildup and allows for slightly more aggressive tuning.", zeroToHundred: "8.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "N/A", notes: "Not financially viable. Upgrading the turbo requires dropping the engine, and the drivetrain cannot handle the power.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" } ],
